/**
 * Keycloak configuration for the Citizen Services Portal.
 *
 * Values are sourced from the environment file:
 *   - Development : src/environments/environment.ts       (localhost defaults)
 *   - Production  : src/environments/environment.prod.ts  (auto-generated by scripts/set-env.js
 *                   which reads Vercel Environment Variables at build time)
 *
 * To add a new environment, add a fileReplacement entry in angular.json and a
 * corresponding environment.<name>.ts file.
 */
import { environment } from '../../environments/environment';

/** Keycloak server config — sourced from the active Angular environment */
export const keycloakConfig = {
  url: environment.keycloak.url,
  realm: environment.keycloak.realm,
  clientId: environment.keycloak.clientId,
};

/** Gateway base URL — all API calls go through here, not directly to microservices */
export const apiGatewayUrl = environment.apiGatewayUrl;
